def close(self, timeout: float) -> dict[str, Any]:
        process = self.process
        escalation = "already-exited"
        if process is not None and process.poll() is None:
            try:
                response = self.request({"id": "shutdown", "method": "shutdown"}, min(timeout, 2.0))
                escalation = "shutdown" if response.get("ok") else "shutdown-error"
            except Exception:
                escalation = "shutdown-error"
            try:
                process.wait(timeout=max(0.2, timeout / 2))
            except subprocess.TimeoutExpired:
                process.terminate()
                escalation = "terminate"
                try:
                    process.wait(timeout=max(0.2, timeout / 3))
                except subprocess.TimeoutExpired:
                    process.kill()
                    escalation = "kill"
                    process.wait(timeout=max(0.2, timeout / 3))
        if process is not None:
            for stream in (process.stdin, process.stdout, process.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
        for reader in (self.stdout_reader, self.stderr_reader):
            if reader is not None:
                reader.join(timeout=2.0)
        exit_code = process.returncode if process is not None else None
        pid = process.pid if process is not None else None
        stderr = list(self.stderr_lines or [])[-20:]
        self.process = None
        self.stdout_queue = None
        self.stdout_reader = None
        self.stderr_reader = None
        self.stderr_lines = None
        self.pending = 0
        return {"escalation": escalation, "server_pid": pid, "exit_code": exit_code, "stderr": stderr}

def serve_stdio(
    output: Path,
    *,
    input_stream: TextIO | None = None,
    output_stream: TextIO | None = None,
    retrieve: Callable[..., dict[str, Any]] | None = None,
    record_explanation: Callable[[Path, dict[str, Any], dict[str, Any]], dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Serve newline-delimited retrieval requests until shutdown or EOF.

    The transport is deliberately local and single-threaded.  Every response
    is one compact JSON line, so a Harness can keep this process alive for one
    task without opening a port or introducing a service dependency.
    """

    output = output.resolve()
    if not (output / "machine/knowledge.sqlite").is_file():
        raise CkbError("machine knowledge is missing; run finalize or machine-reindex")
    if input_stream is None and hasattr(sys.stdin, "reconfigure"):
        sys.stdin.reconfigure(encoding="utf-8", errors="strict", newline="\n")
    if output_stream is None and hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="strict", newline="\n", write_through=True)
    source = input_stream or sys.stdin
    destination = output_stream or sys.stdout
    retrieve_value = retrieve or retrieve_machine
    record_value = record_explanation or _record_explanation
    retrievals: dict[str, dict[str, Any]] = {}
    handled = 0
    succeeded = 0
    failed = 0
    shutdown = False
    for raw_line in source:
        line = raw_line.strip()
        if not line:
            continue
        handled += 1
        request_id: Any = None
        method: Any = None
        started = time.perf_counter_ns()
        try:
            request = json.loads(line)
            if not isinstance(request, dict):
                raise CkbError("stdio request must be a JSON object")
            request_id = request.get("id")
            if not isinstance(request_id, (str, int)) or isinstance(request_id, bool):
                raise CkbError("stdio request id must be a string or integer")
            method = request.get("method")
            if method == "ping":
                result = {
                    "status": "ready",
                    "protocol": STDIO_RETRIEVAL_PROTOCOL,
                    "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
                    "output": str(output),
                    "methods": [
                        "ping",
                        "retrieve",
                        "brief",
                        "entity",
                        "neighbors",
                        "source",
                        "changes",
                        "record-explanation",
                        "shutdown",
                    ],
                }
            elif method in {"retrieve", "brief"}:
                question = request.get("question")
                if not isinstance(question, str) or not question.strip():
                    raise CkbError("stdio retrieve question must be a non-empty string")
                question = _utf8_safe(question).strip()
                budget = _integer(request.get("budget", 1500), "budget", 200, 1_000_000)
                max_pages = _integer(request.get("max_pages", 8), "max_pages", 1, 32)
                profile = request.get("profile", "fast")
                if profile not in {"fast", "precise"}:
                    raise CkbError("stdio retrieve profile must be fast or precise")
                keyword_fallback = _keyword_fallback_options(request)
                if keyword_fallback is None:
                    result = retrieve_value(output, question, budget, max_pages, profile)
                else:
                    result = retrieve_value(
                        output,
                        question,
                        budget,
                        max_pages,
                        profile,
                        keyword_fallback=keyword_fallback,
                    )
                if result.get("status") != "passed" or not result.get("pack"):
                    raise CkbError("stdio retrieve did not return a passed Agent pack")
                retrievals[str(request_id)] = {**result, "request_id": str(request_id)}
                if method == "brief":
                    result = compact_agent_brief(output, result)
            elif method == "entity":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio entity selector must be a non-empty string")
                result = entity_lookup(output, _utf8_safe(selector).strip())
            elif method == "neighbors":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio neighbors selector must be a non-empty string")
                depth = _integer(request.get("depth", 1), "depth", 1, 8)
                limit = _integer(request.get("limit", 50), "limit", 1, 500)
                relation = request.get("relation")
                if relation is not None and not isinstance(relation, str):
                    raise CkbError("stdio neighbors relation must be a string")
                result = neighbor_lookup(output, _utf8_safe(selector).strip(), depth, relation, limit)
            elif method == "source":
                selector = request.get("selector")
                if not isinstance(selector, str) or not selector.strip():
                    raise CkbError("stdio source selector must be a non-empty string")
                context_lines = _integer(request.get("context_lines", 3), "context_lines", 0, 100)
                result = source_lookup(output, _utf8_safe(selector).strip(), context_lines)
            elif method == "changes":
                kind = request.get("kind")
                if kind is not None and not isinstance(kind, str):
                    raise CkbError("stdio changes kind must be a string")
                limit = _integer(request.get("limit", 20), "limit", 1, 500)
                result = change_documents(output, kind, limit)
            elif method == "record-explanation":
                retrieval_id = request.get("retrieval_request_id")
                if not isinstance(retrieval_id, (str, int)) or isinstance(retrieval_id, bool):
                    raise CkbError("stdio record-explanation retrieval_request_id must be a string or integer")
                retrieval = retrievals.get(str(retrieval_id))
                if retrieval is None:
                    raise CkbError("stdio record-explanation requires a completed retrieval from this server session")
                result = record_value(output, request, retrieval)
            elif method == "shutdown":
                result = {"status": "shutting-down"}
                shutdown = True
            else:
                raise CkbError(
                    "stdio request method must be ping, retrieve, brief, entity, neighbors, source, "
                    "changes, record-explanation, or shutdown"
                )
            succeeded += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": True,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "result": result,
                },
            )
        except (json.JSONDecodeError, CkbError) as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": exc.exit_code if isinstance(exc, CkbError) else 2,
                    },
                },
            )
        except Exception as exc:
            failed += 1
            _write_line(
                destination,
                {
                    "id": request_id,
                    "ok": False,
                    "method": method,
                    "elapsed_ms": round((time.perf_counter_ns() - started) / 1_000_000, 6),
                    "error": {
                        "type": type(exc).__name__,
                        "message": str(exc),
                        "exit_code": 1,
                    },
                },
            )
        if shutdown:
            break
    return {
        "schema_version": 1,
        "status": "stopped",
        "protocol": STDIO_RETRIEVAL_PROTOCOL,
        "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
        "requests": handled,
        "succeeded": succeeded,
        "failed": failed,
        "shutdown_requested": shutdown,
    }

def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

#!/usr/bin/env python3
"""Create reproducible core and Obsidian-plugin archives with strict boundaries."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import zipfile
from pathlib import Path, PurePosixPath


VERSION = "5.4.0"
ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", ".mypy_cache"}
CORE_EXCLUDED_TOP_LEVEL = {"plugins"}
RUNTIME_PREFIX = ("assets", "runtime", "win-x64")
PLUGIN_ROOT = ROOT / "plugins" / "obsidian-code-knowledge-builder"
PLUGIN_FILES = ("main.js", "manifest.json", "styles.css", "LICENSE", "NOTICE.md", "build-record.json", "deploy.py")
CORE_REQUIRED_FILES = (
    "SKILL.md",
    "agents/openai.yaml",
    "scripts/ckb.py",
    "scripts/ckb_core/__init__.py",
    "references/workflow.md",
    "references/runtime.md",
    "toolchain.lock.json",
    "THIRD_PARTY_NOTICES.md",
)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for current, directories, filenames in os.walk(ROOT):
        directory = Path(current)
        retained_directories: list[str] = []
        for name in sorted(directories):
            relative = (directory / name).relative_to(ROOT)
            if any(part in EXCLUDED_PARTS for part in relative.parts):
                continue
            if relative.parts and relative.parts[0] in CORE_EXCLUDED_TOP_LEVEL:
                continue
            if not include_runtime and relative.parts[:3] == RUNTIME_PREFIX:
                continue
            retained_directories.append(name)
        directories[:] = retained_directories
        for name in sorted(filenames):
            path = directory / name
            relative = path.relative_to(ROOT)
            if path.suffix in {".pyc", ".pyo"}:
                continue
            result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())


def core_capabilities(kind: str) -> dict[str, bool]:
    return {
        "source_scanning": True,
        "machine_sqlite_knowledge": True,
        "deterministic_retrieval": True,
        "human_markdown_obsidian_vault": True,
        "logseq_projection": True,
        "local_scope_and_segmented_build": True,
        "agent_review_and_audit": True,
        "automation_adapters": True,
        "session_scoped_stdio": True,
        "bundled_offline_runtime": kind == "full-win-x64",
        "obsidian_companion_plugin": False,
    }


def validate_core_boundary() -> None:
    lite = {path.relative_to(ROOT).as_posix() for path in source_files(False)}
    full = {path.relative_to(ROOT).as_posix() for path in source_files(True)}
    missing = sorted(set(CORE_REQUIRED_FILES) - lite)
    if missing:
        raise RuntimeError(f"lite core capability files are absent: {missing}")
    if any(path == "plugins" or path.startswith("plugins/") for path in lite | full):
        raise RuntimeError("core distributions must not contain plugins/")
    if not lite < full:
        raise RuntimeError("full-win-x64 must strictly extend lite")
    unexpected = sorted(
        path for path in full - lite
        if not path.startswith("assets/runtime/win-x64/")
    )
    if unexpected:
        raise RuntimeError(f"full-win-x64 adds non-runtime files: {unexpected}")


def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path


def build_core(kind: str, dist: Path) -> dict:
    lock = json.loads((ROOT / "toolchain.lock.json").read_text(encoding="utf-8"))
    validate_core_boundary()
    include_runtime = kind == "full-win-x64"
    if include_runtime:
        validate_full_payload(lock)
    files = source_files(include_runtime)
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder",
        "version": VERSION,
        "distribution": kind,
        "category": "core",
        "capabilities": core_capabilities(kind),
        "extends": "lite" if include_runtime else None,
        "forbidden_prefixes": ["plugins/"],
        "only_adds_prefix": "assets/runtime/win-x64/" if include_runtime else None,
        "toolchain_lock_id": lock["lock_id"],
        "files": [
            {
                "path": path.relative_to(ROOT).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-{kind}-{VERSION}.zip"
    if archive_path.exists():
        archive_path.unlink()
    prefix = PurePosixPath("code-knowledge-builder")
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            relative = PurePosixPath(path.relative_to(ROOT).as_posix())
            info = zipfile.ZipInfo(str(prefix / relative), date_time=(2026, 8, 26, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
        manifest_info = zipfile.ZipInfo(str(prefix / "distribution" / "release-manifest.json"), date_time=(2026, 8, 26, 0, 0, 0))
        manifest_info.compress_type = zipfile.ZIP_DEFLATED
        manifest_info.external_attr = 0o100644 << 16
        archive.writestr(manifest_info, json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8") + b"\n")
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"ZIP CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(str(prefix / "distribution" / "release-manifest.json")))
        if archived_manifest != manifest:
            raise RuntimeError("archived release manifest differs from the generated manifest")
    result = {
        "status": "passed",
        "distribution": kind,
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-{kind}-{VERSION}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def validate_plugin_dist() -> tuple[str, list[Path], dict]:
    dist = PLUGIN_ROOT / "dist"
    files = [dist / name for name in PLUGIN_FILES]
    missing = [path.name for path in files if not path.is_file() or path.stat().st_size == 0]
    if missing:
        raise RuntimeError(f"Obsidian plugin dist files are absent: {missing}")
    manifest = json.loads((dist / "manifest.json").read_text(encoding="utf-8"))
    version = manifest.get("version")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Obsidian plugin version is absent from manifest.json")
    build_record = json.loads((dist / "build-record.json").read_text(encoding="utf-8"))
    if build_record.get("status") != "passed":
        raise RuntimeError("Obsidian plugin build-record.json has not passed")
    recorded = {item["path"]: item for item in build_record.get("files", [])}
    for path in files:
        if path.name == "build-record.json":
            continue
        item = recorded.get(path.name)
        if not item:
            raise RuntimeError(f"Obsidian plugin build record is missing: {path.name}")
        if int(item.get("size", -1)) != path.stat().st_size or item.get("sha256") != sha256(path):
            raise RuntimeError(f"Obsidian plugin dist differs from build record: {path.name}")
    return version, files, build_record


def build_plugin(dist: Path) -> dict:
    version, files, build_record = validate_plugin_dist()
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder-obsidian",
        "version": version,
        "distribution": "obsidian-plugin",
        "category": "plugin",
        "requires": {
            "knowledge_base": "CKB output with machine/knowledge.sqlite",
            "core_package": "installed separately",
        },
        "bundled_core": False,
        "bundled_offline_runtime": False,
        "agent_deploy": {
            "standalone": "python deploy.py deploy --vault VAULT",
            "core": "ckb.py obsidian-plugin register/deploy/status/remove",
            "auto_deploy_after_registration": True,
        },
        "files": [
            {"path": path.name, "size": path.stat().st_size, "sha256": sha256(path)}
            for path in files
        ],
        "upstream_commit": build_record.get("claudian_commit"),
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-obsidian-{version}.zip"
    if archive_path.exists():
        archive_path.unlink()
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            info = zipfile.ZipInfo(path.name, date_time=(2026, 8, 30, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Obsidian plugin ZIP CRC failed: {bad_member}")
        if archive.namelist() != list(PLUGIN_FILES):
            raise RuntimeError("Obsidian plugin ZIP member set or order differs")
        for path in files:
            if archive.read(path.name) != path.read_bytes():
                raise RuntimeError(f"Obsidian plugin ZIP bytes differ: {path.name}")
    result = {
        "status": "passed",
        "distribution": "obsidian-plugin",
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-obsidian-{version}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def build(kind: str, dist: Path) -> dict:
    if kind == "obsidian-plugin":
        return build_plugin(dist)
    return build_core(kind, dist)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--kind",
        choices=("lite", "full-win-x64", "obsidian-plugin", "both", "all"),
        required=True,
    )
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    if args.kind == "both":
        kinds = ("lite", "full-win-x64")
    elif args.kind == "all":
        kinds = ("lite", "full-win-x64", "obsidian-plugin")
    else:
        kinds = (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

